('p1_ser03_learning',1,'P1SER03-L01',null,'P1-SER-03','learning',false),('p1_ser03_learning',2,'P1SER03-L02',null,'P1-SER-03','learning',false),('p1_ser03_learning',3,'P1SER03-L03',null,'P1-SER-03','learning',false),('p1_ser03_learning',4,null,'P1SER03-W01','P1-SER-03','written',false),
('p1_ser04_learning',1,'P1SER04-L01',null,'P1-SER-04','learning',false),('p1_ser04_learning',2,'P1SER04-L02',null,'P1-SER-04','learning',false),('p1_ser04_learning',3,'P1SER04-L03',null,'P1-SER-04','learning',false),('p1_ser04_learning',4,null,'P1SER04-W01','P1-SER-04','written',false),
('p1_ser05_learning',1,'P1SER05-L01',null,'P1-SER-05','learning',false),('p1_ser05_learning',2,'P1SER05-L02',null,'P1-SER-05','learning',false),('p1_ser05_learning',3,'P1SER05-L03',null,'P1-SER-05','learning',false),('p1_ser05_learning',4,null,'P1SER05-W01','P1-SER-05','written',false),
